param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/weapons-stopped-b.rws'))
# Read-only extraction of explicit original-game XML. No assembly execution.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Num($node){if($null -eq $node){return 0.0};[double]::Parse($node.InnerText,[Globalization.CultureInfo]::InvariantCulture)}
function Stack($node){if($node.SelectSingleNode('stackCount')){return [int]$node.stackCount};1}
function Item($node){[ordered]@{id=[string]$node.id;def=[string]$node.def;stuff=[string]$node.stuff;quality=[string]$node.quality;quality_field_present=($null -ne $node.SelectSingleNode('quality'));health=[int]$node.health;count=(Stack $node);pos=[string]$node.pos;forbidden=([string]$node.forbidden -eq 'True');forbidden_field_present=($null -ne $node.SelectSingleNode('forbidden'));spawned_tick=[int]$node.spawnedTick;despawned_tick=[int]$node.despawnedTick}}
$p=$s.SelectSingleNode('//thing[id="Human961"]');$d=$p.SelectSingleNode('jobs/curDriver');$skill=$p.SelectSingleNode('skills/skills/li[def="Crafting"]')
$worker=[ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;crafting=[ordered]@{level=[int]$skill.level;xp_since_level=(Num $skill.SelectSingleNode('xpSinceLastLevel'))};equipment=@($p.SelectNodes('equipment/equipment/innerList/li')|ForEach-Object{Item $_});inventory=@($p.SelectNodes('inventory/innerContainer/innerList/li')|ForEach-Object{Item $_});carried=@($p.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{Item $_});job=[ordered]@{def=[string]$p.jobs.curJob.def;target_a=[string]$p.jobs.curJob.targetA;target_b=[string]$p.jobs.curJob.targetB;target_c=[string]$p.jobs.curJob.targetC;bill=[string]$p.jobs.curJob.bill;count=[int]$p.jobs.curJob.count;player_forced=([string]$p.jobs.curJob.playerForced -eq 'True');driver=[string]$d.Class;toil_index=[int]$d.curToilIndex;ticks_left=[int]$d.ticksLeftThisToil;start_tick=[int]$d.startTick;work_left=(Num $d.SelectSingleNode('workLeft'));bill_start_tick=[int]$d.billStartTick;ticks_spent_recipe=[int]$d.ticksSpentDoingRecipeWork};work_priority_values=@($p.SelectNodes('workSettings/priorities/vals/li')|ForEach-Object{[int]$_.InnerText})}
# Limit material/weapon inventory to the active map subtree, including its pawn
# containers and unfinished items. World-pawn and off-map equipment are excluded.
$map=$p.ParentNode.ParentNode
$wood=@($map.SelectNodes('.//*[def="WoodLog" and id]')|ForEach-Object{[ordered]@{id=[string]$_.id;count=(Stack $_);pos=[string]$_.pos;parent=$_.ParentNode.Name;ingredient_of=if($_.ParentNode.Name -eq 'ingredients'){[string]$_.ParentNode.ParentNode.id}else{''};forbidden=([string]$_.forbidden -eq 'True')}}|Sort-Object {$_.id})
$spots=@($map.SelectNodes('./things/thing[def="CraftingSpot"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;spawned_tick=[int]$_.spawnedTick;bills=@($_.SelectNodes('billStack/bills/li')|ForEach-Object{[ordered]@{id=[int]$_.loadID;recipe=[string]$_.recipe;repeat_mode=[string]$_.repeatMode;repeat_count=[int]$_.repeatCount;repeat_count_field_present=($null -ne $_.SelectSingleNode('repeatCount'));store_mode=[string]$_.storeMode;bound_uft=[string]$_.boundUft;allowed_materials=@($_.SelectNodes('ingredientFilter/allowedDefs/li')|ForEach-Object{$_.InnerText})}})}})
$unfinished=@($map.SelectNodes('.//*[def="UnfinishedWeapon" and id]')|ForEach-Object{[ordered]@{id=[string]$_.id;stuff=[string]$_.stuff;recipe=[string]$_.recipe;bill=[string]$_.bill;creator=[string]$_.creator;pos=[string]$_.pos;spawned_tick=[int]$_.spawnedTick;work_left=(Num $_.SelectSingleNode('workLeft'));ingredients=@($_.SelectNodes('ingredients/li')|ForEach-Object{Item $_})}})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;worker=$worker;ground_weapons=@($map.SelectNodes('./things/thing[starts-with(def,"MeleeWeapon_") or starts-with(def,"Gun_")]')|ForEach-Object{Item $_}|Sort-Object {$_.id});wood=$wood;wood_total=[int](($wood|Measure-Object -Property count -Sum).Sum);spots=$spots;unfinished=$unfinished;scope='Read-only explicit XML. Active map subtree only for ground weapons and wood (including pawn and unfinished containers); world-pawn gear excluded. Omitted forbidden is false; omitted quality remains absent, not Normal. Other omitted numeric fields use zero; repeatCount presence retained. Work-priority vector is not decoded.'}|ConvertTo-Json -Depth 24
